   witnesses.append({'observation_id':o['observation_id'],'requirement_id':requirement['requirement_id'],'dimension':requirement['dimension'],'candidate_uri':uri,'explicit_graph_term_present':present if uri else None,'graph_labels':[str(v) for v in g.objects(URIRef(uri),RDFS.label)] if uri else [],'presence_claim_class':'MEASURED PROJECT RESULT','dimension_alignment_claim_class':'PROJECT ASSESSMENT','scientific_expressibility':None,'scope':'Presence verifies an observation-model building block only, not exact quantity/support semantics or an approved mapping'})
