 import numpy as np
 ids=sorted({r['resource_id'] for r in rows});dims=sorted({r['dimension'] for r in rows});index={(r['resource_id'],r['dimension']):r['score'] for r in rows}
 complete=[d for d in dims if any(index[(i,d)] is not None for i in ids)]
 complete_ids=[i for i in ids if all(index[(i,d)] is not None for d in complete)]
