 inputs=[ROOT/'tests/test_scientific_validation.py',ROOT/'pyproject.toml',ROOT/'AGENTS.md',ROOT/'README.md',ROOT/'data/fixtures/validation/decision_tasks.json',ROOT/'data/semantics/semantic_resources.csv',*sorted((ROOT/'data/semantics/validation').glob('*.json')),*sorted((REPORT/'data/graphs').glob('*')),ROOT/'run/scoped-sentinel-bundle.json',ROOT/'run/sentinel-stream-consensus-bounded/proposed_recipe.json',ROOT/'run/scoped-sentinel-review-v4/report.json',ROOT/'run/sentinel-stream-plan.json',REPORT/'data/neon-product.json',REPORT/'data/neon-site.json',ROOT/'src/dataset_prototype/scientific_validation.py',ROOT/'src/dataset_prototype/decision_experiment.py',Path(__file__)]
 manifest={'version':VERSION,'generated_at':datetime.now(timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'code_and_input_hashes':[{'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in inputs],'versions':{x:md.version(x) for x in ['dataset-prototype','cubedynamics','rdflib','numpy','pydantic']},'source_data_read':False,'execution_authorized':False,'counts':{'resources':len(resources),'breadth_assertions':len(rows),'canonical_observations':len(observations),'candidate_records':len(datasets['records']),'dataset_pairs':len(datasets['pairs']),'parsed_graphs':sum('triples' in g for g in graphs),'sentinel_review_issues':len(package['blockers'])},'limits':['Dimension coverage is an assessment-based diagnostic, not term-level scientific expressibility','Human gold pending; no scientific decision accuracy established','NEON observations and sensor metadata missing','Prior vetoes preserved; no scientific execution approved','Only three ontology graphs measured; no imports followed'],'outputs':[]}
